(2688711, 370497, 13487, '<td valign="top">This is a very neat photo but I dont see how you relate it to action.  I''m not sure if this was staged or if you were just waiting for the right moment but the only suggestion I would make is to have the two doors open the same amount.  The left door for instance is a little distracting with the over exposed portion.</td>', 'This is a very neat photo but I dont see how you relate it to action.  I''m not sure if this was staged or if you were just waiting for the right moment but the only suggestion I would make is to have the two doors open the same amount.  The left door for instance is a little distracting with the over exposed portion.', '2006-08-02 14:28:44.000000', NULL, 1),
(2688763, 372646, 62006, '<td valign="top">Nice Shot</td>', 'Nice Shot', '2006-08-02 14:40:35.000000', NULL, 1),
(2688766, 372654, 62006, '<td valign="top">Grainy and out of focus</td>', 'Grainy and out of focus', '2006-08-02 14:41:24.000000', NULL, 1);
