(2688777, 373756, 62006, '<td valign="top">Love the colors in this shot</td>', 'Love the colors in this shot', '2006-08-02 14:43:33.000000', NULL, 1),
(2688778, 373710, 62006, '<td valign="top">Iwant a kite...looks like fun. Good job</td>', 'Iwant a kite...looks like fun. Good job', '2006-08-02 14:44:06.000000', NULL, 1),
