(2689326, 372310, 62554, '<td valign="top">Shame your position was not a little further forward.  Feel this could have been improved, action wise, by a severe crop amongst the competitors.  There is too much info for the viewer.  The crop would encompass some splash and a bunch of the compets diving in.</td>', 'Shame your position was not a little further forward.  Feel this could have been improved, action wise, by a severe crop amongst the competitors.  There is too much info for the viewer.  The crop would encompass some splash and a bunch of the compets diving in.', '2006-08-02 17:21:18.000000', NULL, 1),
(2689330, 372777, 62554, '<td valign="top">Very nice pan.  Score of 7 (4 + 3)</td>', 'Very nice pan.  Score of 7 (4 + 3)', '2006-08-02 17:21:58.000000', NULL, 1),
(2689332, 371759, 62554, '<td valign="top">Too much action for me ...</td>', 'Too much action for me ...', '2006-08-02 17:22:19.000000', NULL, 1),
