(2689449, 373610, 60223, '<td valign="top">Many times better if it had been hitting someone.  Kinda of borning with just the brick wall.  As for the action, you''ve captured the water balloon well.</td>', 'Many times better if it had been hitting someone.  Kinda of borning with just the brick wall.  As for the action, you''ve captured the water balloon well.', '2006-08-02 18:17:53.000000', NULL, 1),
(2689454, 373738, 60223, '<td valign="top">I think that the moment was frozen so fast that the action has almost all but been removed from this photo, a little more motion blur would have been nice for this challenge.</td>', 'I think that the moment was frozen so fast that the action has almost all but been removed from this photo, a little more motion blur would have been nice for this challenge.', '2006-08-02 18:19:45.000000', NULL, 1),
(2689458, 373285, 60223, '<td valign="top">Nice action shot.  Is the picture tilted to the right?</td>', 'Nice action shot.  Is the picture tilted to the right?', '2006-08-02 18:21:10.000000', NULL, 1),
(2689461, 373645, 60223, '<td valign="top">Looking at this photo it feels like I''m zooming down the hill myself.  Good job.</td>', 'Looking at this photo it feels like I''m zooming down the hill myself.  Good job.', '2006-08-02 18:22:07.000000', NULL, 1),
