INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2690130, 372897, 41200, '<td valign="top">Nice shot. I would have given the title a little more punch though...maybe "Friday Knight Fights". Well done.</td>', 'Nice shot. I would have given the title a little more punch though...maybe "Friday Knight Fights". Well done.', '2006-08-02 22:43:20.000000', NULL, 1),
(2690134, 372952, 19708, '<td valign="top">Always fun to freeze someone mid-stride like this. Good timing.</td>', 'Always fun to freeze someone mid-stride like this. Good timing.', '2006-08-02 22:44:08.000000', NULL, 1),
(2690137, 370565, 28029, '<td valign="top">The bird itself is wonderful. I even like the motion blur on the wings. But the background is horrible. You either needed to shoot in a different direction or reduce your f stop to increase depth of field 6</td>', 'The bird itself is wonderful. I even like the motion blur on the wings. But the background is horrible. You either needed to shoot in a different direction or reduce your f stop to increase depth of field 6', '2006-08-02 22:44:29.000000', NULL, 1),
(2690138, 373645, 19708, '<td valign="top">Excellent pan and technicals on this - riding into the frame, colors and angle all add up to a very pleasing image. Well done!</td>', 'Excellent pan and technicals on this - riding into the frame, colors and angle all add up to a very pleasing image. Well done!', '2006-08-02 22:45:16.000000', NULL, 1),
(2690149, 372967, 28029, '<td valign="top">Like the idea. I think that it lacks crispness (sharpness), and contrast. 6</td>', 'Like the idea. I think that it lacks crispness (sharpness), and contrast. 6', '2006-08-02 22:47:28.000000', NULL, 1),
(2690152, 372921, 30669, '<td valign="top">Great Shot</td>', 'Great Shot', '2006-08-02 22:47:52.000000', NULL, 1),
(2690158, 373003, 28029, '<td valign="top">I like this alot, however, I would have liked a different crop. It appears that you were trying to make the hand on the flat water as the focal point but I would not agree with that for 2 reasons: 1) The lighting does not support it with the hand in shadows and 2) the action of the spray coming off the foot is the real grabber. The hand on the smooth water is gravy not the main course. 8</td>', 'I like this alot, however, I would have liked a different crop. It appears that you were trying to make the hand on the flat water as the focal point but I would not agree with that for 2 reasons: 1) The lighting does not support it with the hand in shadows and 2) the action of the spray coming off the foot is the real grabber. The hand on the smooth water is gravy not the main course. 8', '2006-08-02 22:50:47.000000', NULL, 1),
(2690168, 372957, 28029, '<td valign="top">What a cute pic</td>', 'What a cute pic', '2006-08-02 22:53:37.000000', NULL, 1),
(2690173, 370497, 28029, '<td valign="top">Very interesting</td>', 'Very interesting', '2006-08-02 22:54:37.000000', NULL, 1),
(2690175, 373645, 30669, '<td valign="top">As a biker (mountain biker) this is great shot.</td>', 'As a biker (mountain biker) this is great shot.', '2006-08-02 22:55:03.000000', NULL, 1),
(2690180, 373710, 28029, '<td valign="top">Love the subject. Just a tad washed out and soft focus. But very fun original pic 7</td>', 'Love the subject. Just a tad washed out and soft focus. But very fun original pic 7', '2006-08-02 22:56:10.000000', NULL, 1),
(2690189, 373688, 28029, '<td valign="top">Clever but the soft focus kills it. 6</td>', 'Clever but the soft focus kills it. 6', '2006-08-02 22:57:28.000000', NULL, 1),
(2690199, 373289, 28029, '<td valign="top">Small file size will hurt you every time. Read how to etc to learn proper file sizing.</td>', 'Small file size will hurt you every time. Read how to etc to learn proper file sizing.', '2006-08-02 22:59:11.000000', NULL, 1),
(2690203, 373302, 22301, '<td valign="top">with the sepia tonng it is abit difficult to distinguish the net from the background</td>', 'with the sepia tonng it is abit difficult to distinguish the net from the background', '2006-08-02 22:59:54.000000', NULL, 1),
(2690204, 373737, 28029, '<td valign="top">I like the de sat but then the title confuses me. Beautiful composition. 8</td>', 'I like the de sat but then the title confuses me. Beautiful composition. 8', '2006-08-02 23:00:04.000000', NULL, 1),
(2690210, 370179, 61818, '<td valign="top">Awesome shot.  I think the foreground telephone pole and the hint of city lights on the horizon combine to really give an excellent sense of scale to the strike.  Colors are great, really don''t have anything negative to say. 9.</td>', 'Awesome shot.  I think the foreground telephone pole and the hint of city lights on the horizon combine to really give an excellent sense of scale to the strike.  Colors are great, really don''t have anything negative to say. 9.', '2006-08-02 23:02:01.000000', NULL, 1),
(2690212, 373531, 61818, '<td valign="top">Love it.  Good composition, crazy subject matter, all around a good shot. 8.</td>', 'Love it.  Good composition, crazy subject matter, all around a good shot. 8.', '2006-08-02 23:02:42.000000', NULL, 1),
(2690219, 371002, 28029, '<td valign="top">Unsettling. Something needs to be in sharp focus. Also the lighting needs work.</td>', 'Unsettling. Something needs to be in sharp focus. Also the lighting needs work.', '2006-08-02 23:03:39.000000', NULL, 1),
(2690222, 373327, 61818, '<td valign="top">What a great action shot, really nailed the challenge theme perfectly.  Love the BW processing and love how you''ve balanced the composition.  Really the only ''bad'' comment I would make is I don''t care for the white line you''ve included in the border.  Other than that, really nice shot. 8.</td>', 'What a great action shot, really nailed the challenge theme perfectly.  Love the BW processing and love how you''ve balanced the composition.  Really the only ''bad'' comment I would make is I don''t care for the white line you''ve included in the border.  Other than that, really nice shot. 8.', '2006-08-02 23:04:12.000000', NULL, 1),
(2690228, 371627, 28029, '<td valign="top">dramatic</td>', 'dramatic', '2006-08-02 23:04:58.000000', NULL, 1),
(2690231, 373305, 61971, '<td valign="top">Good Capture. The picture is a little small though.</td>', 'Good Capture. The picture is a little small though.', '2006-08-02 23:05:29.000000', NULL, 1),
(2690232, 373504, 61818, '<td valign="top">Great action shot!  Love the composition though I think cropping so the guy is a bit higher in the shot would add even more excitement.  Also think processing for a bit more color in the sky might have given it a little more pop, but what a great shot overall. 7.</td>', 'Great action shot!  Love the composition though I think cropping so the guy is a bit higher in the shot would add even more excitement.  Also think processing for a bit more color in the sky might have given it a little more pop, but what a great shot overall. 7.', '2006-08-02 23:05:45.000000', NULL, 1),
(2690234, 372241, 59222, '<td valign="top">Wow, would have been great for the "Color on Color" challenge last week, too!</td>', 'Wow, would have been great for the "Color on Color" challenge last week, too!', '2006-08-02 23:05:59.000000', NULL, 1),
(2690239, 373600, 61818, '<td valign="top">Really nice shot, meets the challenge well.  The composition is well balanced, the colors work great.  Good contrast - everything jumps out at you.  Only thing that distracts me a bit is the flash being very harsh on the chunk of snow nearest the camera.  Really nice work, good job. 7.</td>', 'Really nice shot, meets the challenge well.  The composition is well balanced, the colors work great.  Good contrast - everything jumps out at you.  Only thing that distracts me a bit is the flash being very harsh on the chunk of snow nearest the camera.  Really nice work, good job. 7.', '2006-08-02 23:07:04.000000', NULL, 1),
(2690245, 373396, 61818, '<td valign="top">Very nice shot, meets the challenge well.  Could live without the border.  Love the motion blur and how the bystander is posed.  It seems to get a bit out of focus around that big light which is a little bit distracting as the light is pretty prominent in the shot.  Love the BW processing.  Good job. 6.</td>', 'Very nice shot, meets the challenge well.  Could live without the border.  Love the motion blur and how the bystander is posed.  It seems to get a bit out of focus around that big light which is a little bit distracting as the light is pretty prominent in the shot.  Love the BW processing.  Good job. 6.', '2006-08-02 23:08:42.000000', NULL, 1),
(2690247, 373600, 28029, '<td valign="top">wow</td>', 'wow', '2006-08-02 23:09:27.000000', NULL, 1),
(2690249, 373383, 61818, '<td valign="top">This is a really nice shot.  I love the processing.  I think it might be a bit more interesting cropped so the guys are more off to the side.  As far as action goes, this isn''t getting my heart pumping but it does show them ''in action'' so it meets the challenge as far as that goes.  nice work, 6.</td>', 'This is a really nice shot.  I love the processing.  I think it might be a bit more interesting cropped so the guys are more off to the side.  As far as action goes, this isn''t getting my heart pumping but it does show them ''in action'' so it meets the challenge as far as that goes.  nice work, 6.', '2006-08-02 23:09:49.000000', NULL, 1),
(2690252, 373308, 28029, '<td valign="top">Enter this in a "Make your own caption" contest.</td>', 'Enter this in a "Make your own caption" contest.', '2006-08-02 23:10:38.000000', NULL, 1),
(2690254, 370921, 61818, '<td valign="top">Really nice.  Meets the challenge well.  Love the BW processing, love the shadows on the concrete.  Could maybe up the contrast a bit so some of the lines on the ground stand out a bit more?  I''m not a big fan of borders and this one doesn''t do anything for me.  Would be a bit better if the kid were more sharply in focus, don''t think the litle bit of motion blur conveys any more action than the pose you captured him in.  Overall a really fine shot, great job. 6.</td>', 'Really nice.  Meets the challenge well.  Love the BW processing, love the shadows on the concrete.  Could maybe up the contrast a bit so some of the lines on the ground stand out a bit more?  I''m not a big fan of borders and this one doesn''t do anything for me.  Would be a bit better if the kid were more sharply in focus, don''t think the litle bit of motion blur conveys any more action than the pose you captured him in.  Overall a really fine shot, great job. 6.', '2006-08-02 23:11:38.000000', NULL, 1),
(2690256, 373420, 61818, '<td valign="top">Dude!  nice shot, meets the challenge well.  Looks a little washed out, maybe up the saturation.  Like the crazy pose the guy is in.  Well done. 6.</td>', 'Dude!  nice shot, meets the challenge well.  Looks a little washed out, maybe up the saturation.  Like the crazy pose the guy is in.  Well done. 6.', '2006-08-02 23:12:35.000000', NULL, 1),
(2690261, 373536, 6366, '<td valign="top">nice shot .I''ve been trying to get the males at my feeder but have failed so far. Very clear .what type of camera and speed</td>', 'nice shot .I''ve been trying to get the males at my feeder but have failed so far. Very clear .what type of camera and speed', '2006-08-02 23:14:56.000000', NULL, 1),
(2690265, 373545, 61818, '<td valign="top">This gives me more a sense of agony than action, but this guy is ''in action'' so I''m thinking it meets the challenge.  Would like to see all of his hanging hair, looks like a bit got cropped out.  Lighting is really good, I think the shadows on his face intensify the effect here.  Might have composed it with the guy off to the side.  Like the DOF, just enough detail on the bystanders to see they are watching intently and make the guy even more the focus of the shot.  Good job, 6.</td>', 'This gives me more a sense of agony than action, but this guy is ''in action'' so I''m thinking it meets the challenge.  Would like to see all of his hanging hair, looks like a bit got cropped out.  Lighting is really good, I think the shadows on his face intensify the effect here.  Might have composed it with the guy off to the side.  Like the DOF, just enough detail on the bystanders to see they are watching intently and make the guy even more the focus of the shot.  Good job, 6.', '2006-08-02 23:16:02.000000', NULL, 1),
(2690269, 373438, 61818, '<td valign="top">Nice shot, loads of action.  Like the composition, do not like the border at all.  So many shots in this challenge managed to crop out part of the subject, I''m glad you got all of the guy and his paddle in here.  Really nothing bad to say, though a slight increase in constrast might give a little more pop to this.  Still, really nice work.  Good job, 6.</td>', 'Nice shot, loads of action.  Like the composition, do not like the border at all.  So many shots in this challenge managed to crop out part of the subject, I''m glad you got all of the guy and his paddle in here.  Really nothing bad to say, though a slight increase in constrast might give a little more pop to this.  Still, really nice work.  Good job, 6.', '2006-08-02 23:18:42.000000', NULL, 1),
(2690271, 373531, 22301, '<td valign="top">Amazing stuff this guy, looks like something I just put in my favs :). So far the best I have seen.</td>', 'Amazing stuff this guy, looks like something I just put in my favs :). So far the best I have seen.', '2006-08-02 23:19:58.000000', NULL, 1),
(2690272, 373346, 61818, '<td valign="top">Like this shot quite a bit.  Great action, great composition.  Love the fact that the subject is nice and sharp.  The smoke trail gives a nice sense of movement without you sacrificing focus for blur.  Looks a little washed out like it could have benefited from some saturation and some curves/contrast boost to give a little more pop.  Overall, really nice entry.  Good job. 5.</td>', 'Like this shot quite a bit.  Great action, great composition.  Love the fact that the subject is nice and sharp.  The smoke trail gives a nice sense of movement without you sacrificing focus for blur.  Looks a little washed out like it could have benefited from some saturation and some curves/contrast boost to give a little more pop.  Overall, really nice entry.  Good job. 5.', '2006-08-02 23:20:34.000000', NULL, 1),
(2690278, 372959, 61818, '<td valign="top">Nice shot.  No real sense of heart pounding action here, but like the other concert shots the performer is ''in action'' so it meets the challenge.  Like the colors and the composition.  Might have cropped it so part of his head didn''t get lopped off on the left.    DOF is good here but also think slightly increased it would have gotten that kids face in focus and that would have added some drama to the shot.  Overall, really nice shot. 5.</td>', 'Nice shot.  No real sense of heart pounding action here, but like the other concert shots the performer is ''in action'' so it meets the challenge.  Like the colors and the composition.  Might have cropped it so part of his head didn''t get lopped off on the left.    DOF is good here but also think slightly increased it would have gotten that kids face in focus and that would have added some drama to the shot.  Overall, really nice shot. 5.', '2006-08-02 23:22:28.000000', NULL, 1),
(2690282, 373715, 61971, '<td valign="top">I very simply don''t like the picture.</td>', 'I very simply don''t like the picture.', '2006-08-02 23:23:35.000000', NULL, 1),
(2690285, 373659, 61818, '<td valign="top">Meets the challenge well.  I like this shot because it is different, colorful and somehow still has the guy on the seat in good focus.  At the same time, the sheer volume of motion blur is a distraction for me.  Possibly cropping out some of that background would have made this a little less busy and made it easier for the eye to focus on the subject.  A nice shot, good work. 5.</td>', 'Meets the challenge well.  I like this shot because it is different, colorful and somehow still has the guy on the seat in good focus.  At the same time, the sheer volume of motion blur is a distraction for me.  Possibly cropping out some of that background would have made this a little less busy and made it easier for the eye to focus on the subject.  A nice shot, good work. 5.', '2006-08-02 23:24:12.000000', NULL, 1),
(2690290, 373742, 61818, '<td valign="top">Nice action, looks good in BW.  Great dof, well composed.  I would toss this another point or two but for the fact that part of his hand and the board are cropped out.  Not sure if that''s by intent or just the way the shot came out of the camera.  Still, really nice photo. 5.</td>', 'Nice action, looks good in BW.  Great dof, well composed.  I would toss this another point or two but for the fact that part of his hand and the board are cropped out.  Not sure if that''s by intent or just the way the shot came out of the camera.  Still, really nice photo. 5.', '2006-08-02 23:25:16.000000', NULL, 1),
(2690302, 373753, 61818, '<td valign="top">This shot meets the challenge, though at the same time it is a pretty boring ''action'' shot.  While the bird is clearly in motion, being set against a washed out sky really removes all sense of excitement/action/movement.  A little bit of the ground in the shot, maybe some play with curves to give some life to that sky (if possible) and I think this would have much more pop.  Nice work, 5.</td>', 'This shot meets the challenge, though at the same time it is a pretty boring ''action'' shot.  While the bird is clearly in motion, being set against a washed out sky really removes all sense of excitement/action/movement.  A little bit of the ground in the shot, maybe some play with curves to give some life to that sky (if possible) and I think this would have much more pop.  Nice work, 5.', '2006-08-02 23:27:29.000000', NULL, 1),
(2690305, 370565, 61971, '<td valign="top">Great shot. IMO it would be better if the wings were not clipped at the top.</td>', 'Great shot. IMO it would be better if the wings were not clipped at the top.', '2006-08-02 23:28:23.000000', NULL, 1),
(2690310, 372967, 61818, '<td valign="top">I love the roaring water here and the overall composition is good.  Certainly meets the action challenge.  I am a big fan of BW photos but this one is a bit washed out and could use some more contrast.  Also nothing here is level.  It is hard, I know, when dealing with an object like the bridge that has lines being drawn back to a vanishing point to figure out what exactly should be straight, but here nothing is perfectly horizontal so it gives the whole photo a sense of being off balance.  Personally I would rotate the shot slightly counterclockwise so the bottom of the bridge span is level or possibly the left embankment stones are level.  Nice work overall.  Good job. 5.</td>', 'I love the roaring water here and the overall composition is good.  Certainly meets the action challenge.  I am a big fan of BW photos but this one is a bit washed out and could use some more contrast.  Also nothing here is level.  It is hard, I know, when dealing with an object like the bridge that has lines being drawn back to a vanishing point to figure out what exactly should be straight, but here nothing is perfectly horizontal so it gives the whole photo a sense of being off balance.  Personally I would rotate the shot slightly counterclockwise so the bottom of the bridge span is level or possibly the left embankment stones are level.  Nice work overall.  Good job. 5.', '2006-08-02 23:30:33.000000', NULL, 1),
(2690314, 370705, 61818, '<td valign="top">Hmm.  On one hand, this shot has enough wow factor to keep me interested.  On the other hand, it''s over saturated and there is too much emptu space above the model.  Not sure how you setup this trick shot, but possibly shooting it from a lower angle would have given more sky space between ground and model, less ground overall and less sky above.  This would increase the sense of ''the jump'' which is really the action here.  Overall a nice shot.  Good work, 5.</td>', 'Hmm.  On one hand, this shot has enough wow factor to keep me interested.  On the other hand, it''s over saturated and there is too much emptu space above the model.  Not sure how you setup this trick shot, but possibly shooting it from a lower angle would have given more sky space between ground and model, less ground overall and less sky above.  This would increase the sense of ''the jump'' which is really the action here.  Overall a nice shot.  Good work, 5.', '2006-08-02 23:32:38.000000', NULL, 1),
(2690318, 373303, 61971, '<td valign="top">Scary. You have more guts than I do!</td>', 'Scary. You have more guts than I do!', '2006-08-02 23:33:30.000000', NULL, 1),
(2690322, 373722, 61818, '<td valign="top">This is great.  Good action and some humor.  I think the off balance pose of the kid goes a long way towards giving the sense of action here, so much so that the motion blur (if intentional) is uneeded and distracting.  Would like to have seen everything sharp and possibly a reduced DOF to blur out some of the background.  Like the composition overall.  Very nice work, good job. 5.</td>', 'This is great.  Good action and some humor.  I think the off balance pose of the kid goes a long way towards giving the sense of action here, so much so that the motion blur (if intentional) is uneeded and distracting.  Would like to have seen everything sharp and possibly a reduced DOF to blur out some of the background.  Like the composition overall.  Very nice work, good job. 5.', '2006-08-02 23:34:34.000000', NULL, 1),
(2690323, 372268, 59222, '<td valign="top">I love bride''s expression :-)</td>', 'I love bride''s expression :-)', '2006-08-02 23:35:25.000000', NULL, 1),
(2690325, 373549, 22301, '<td valign="top">nice use of the upside down move. with so much of the phot reflection it really through off the viewers equilibrium.</td>', 'nice use of the upside down move. with so much of the phot reflection it really through off the viewers equilibrium.', '2006-08-02 23:36:01.000000', NULL, 1),
(2690327, 371465, 61971, '<td valign="top">Stunning!</td>', 'Stunning!', '2006-08-02 23:36:16.000000', NULL, 1),
(2690329, 373291, 61818, '<td valign="top">This was a great action shot. Some problems here for me are too much whitewater below the guy and the lack of contrast between parachute and that dark cloud.  Cropping it a bit tighter would elminate some of the whitewater while still showing that nice ocean blue-green and the whitecaps of that rough sea.  hard to deal with the dark cloud there, so that''s life.  Good shot overall, 5.</td>', 'This was a great action shot. Some problems here for me are too much whitewater below the guy and the lack of contrast between parachute and that dark cloud.  Cropping it a bit tighter would elminate some of the whitewater while still showing that nice ocean blue-green and the whitecaps of that rough sea.  hard to deal with the dark cloud there, so that''s life.  Good shot overall, 5.', '2006-08-02 23:37:29.000000', NULL, 1),
(2690332, 372949, 61818, '<td valign="top">Hmm, is this the shot I saw in the forums where someone was asking how to get rid of the netting?  Heheh.  Nice shot, well composed.  The netting doesn''t ruin it for me.  Nice work, 5.</td>', 'Hmm, is this the shot I saw in the forums where someone was asking how to get rid of the netting?  Heheh.  Nice shot, well composed.  The netting doesn''t ruin it for me.  Nice work, 5.', '2006-08-02 23:38:37.000000', NULL, 1),
(2690335, 373748, 22301, '<td valign="top">hey feels like I have seen this some where before, hmmmmm. New lens seems to be working great, nice and sharp. I think it might have been nice to have the entire board in the photo.</td>', 'hey feels like I have seen this some where before, hmmmmm. New lens seems to be working great, nice and sharp. I think it might have been nice to have the entire board in the photo.', '2006-08-02 23:39:08.000000', NULL, 1),
(2690337, 372901, 61818, '<td valign="top">Looks like the guy in white just smacked the guy in black in the head.  Tipped horizons are never fun and this would be a bit more interesting with the guys off to one side or the other.  Like your DOF here and nice saturation on the colors.  Great capture of the action with no motion blur.  nice work. 5.</td>', 'Looks like the guy in white just smacked the guy in black in the head.  Tipped horizons are never fun and this would be a bit more interesting with the guys off to one side or the other.  Like your DOF here and nice saturation on the colors.  Great capture of the action with no motion blur.  nice work. 5.', '2006-08-02 23:40:11.000000', NULL, 1),
(2690340, 372688, 59222, '<td valign="top">I like it, but I get the impression the bike is turning to the right (towards the camera) ?</td>', 'I like it, but I get the impression the bike is turning to the right (towards the camera) ?', '2006-08-02 23:40:24.000000', NULL, 1),
(2690341, 372278, 22301, '<td valign="top">I like the action of the rider, but I thnk I like even more all the photographers taking shots of the rider.</td>', 'I like the action of the rider, but I thnk I like even more all the photographers taking shots of the rider.', '2006-08-02 23:40:26.000000', NULL, 1),
(2690350, 371547, 61818, '<td valign="top">Nice shot here, plenty of action.  Could use a little more contrast to get the guy and his jet ski to jump out from that wall of water.  Well composed and a rare instance of a border that doesn''t bother my eyes.  Nice photo, good work. 5.</td>', 'Nice shot here, plenty of action.  Could use a little more contrast to get the guy and his jet ski to jump out from that wall of water.  Well composed and a rare instance of a border that doesn''t bother my eyes.  Nice photo, good work. 5.', '2006-08-02 23:42:59.000000', NULL, 1),
(2690355, 370820, 22301, '<td valign="top">your title made laugh, bonus point to you</td>', 'your title made laugh, bonus point to you', '2006-08-02 23:45:17.000000', NULL, 1),
(2690370, 370179, 59442, '<td valign="top">Way Kewl!</td>', 'Way Kewl!', '2006-08-02 23:57:21.000000', NULL, 1),
(2690401, 373330, 37730, '<td valign="top">9 :)  definitely rocking.</td>', '9 :)  definitely rocking.', '2006-08-03 00:13:31.000000', NULL, 1),
(2690410, 371114, 37730, '<td valign="top">8 :) a great game and age.  nice photo.</td>', '8 :) a great game and age.  nice photo.', '2006-08-03 00:17:36.000000', NULL, 1),
(2690528, 372687, 19708, '<td valign="top">Assuming this wasn''t done with strobes, which really freeze the action, my hat is off (if I had one) to you for the timing on this. Let me guess - 23 lightbulbs to get it right? jk</td>', 'Assuming this wasn''t done with strobes, which really freeze the action, my hat is off (if I had one) to you for the timing on this. Let me guess - 23 lightbulbs to get it right? jk', '2006-08-03 00:46:25.000000', NULL, 1),
(2690530, 373710, 19708, '<td valign="top">There is a lot of action stopped in this - a good freeze frame.<br/>Those kites look like squids!</td>', 'There is a lot of action stopped in this - a good freeze frame.Those kites look like squids!', '2006-08-03 00:47:32.000000', NULL, 1),
(2690538, 373148, 19708, '<td valign="top">Really clean shot!<br/>DoF and the levels/tones work well.</td>', 'Really clean shot!DoF and the levels/tones work well.', '2006-08-03 00:48:51.000000', NULL, 1),
(2690549, 373531, 19708, '<td valign="top">This shot stopped me in my tracks.<br/>I don''t know if I should close my eyes or wait to see the outtakes.<br/>Wow!</td>', 'This shot stopped me in my tracks.I don''t know if I should close my eyes or wait to see the outtakes.Wow!', '2006-08-03 00:50:29.000000', NULL, 1),
(2690621, 372179, 16106, '<td valign="top">Bigger is better. nice motion stop, but the detail in the water is lessened by the less than 640 pixel count on the long side.</td>', 'Bigger is better. nice motion stop, but the detail in the water is lessened by the less than 640 pixel count on the long side.', '2006-08-03 01:14:48.000000', NULL, 1),
