(2693143, 373327, 51538, '<td valign="top">Love the speed and strength that you caught in this photo.  Very nice timing.  The splatter shows a great shutter speed. 9.</td>', 'Love the speed and strength that you caught in this photo.  Very nice timing.  The splatter shows a great shutter speed. 9.', '2006-08-03 18:48:18.000000', NULL, 1),
(2693146, 373097, 51538, '<td valign="top">Nice crisp focus on the face and good colours. 8.</td>', 'Nice crisp focus on the face and good colours. 8.', '2006-08-03 18:49:19.000000', NULL, 1),
(2693149, 370977, 51538, '<td valign="top">Amazons or Swedes.  Whatever, you have caught them at a moment of intense action with a very nice shutter speed and exposure. 8.</td>', 'Amazons or Swedes.  Whatever, you have caught them at a moment of intense action with a very nice shutter speed and exposure. 8.', '2006-08-03 18:50:15.000000', NULL, 1),
(2693151, 373756, 51538, '<td valign="top">Yes, just a millisecond.  And you caught it with a good focus and shutter speed. 8.</td>', 'Yes, just a millisecond.  And you caught it with a good focus and shutter speed. 8.', '2006-08-03 18:50:59.000000', NULL, 1),
(2693154, 373526, 51538, '<td valign="top">Very nice crisp photo.  Perfect shutter speed and exposure.  9.</td>', 'Very nice crisp photo.  Perfect shutter speed and exposure.  9.', '2006-08-03 18:51:54.000000', NULL, 1),
(2693156, 373062, 51538, '<td valign="top">Wet running there.  As an English person I am more used to seeing sodden turf fly.  But you caught the action with a nice shutter speed and exposure. 8.</td>', 'Wet running there.  As an English person I am more used to seeing sodden turf fly.  But you caught the action with a nice shutter speed and exposure. 8.', '2006-08-03 18:52:53.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2693159, 373753, 51538, '<td valign="top">A black-headed tern, I think.  Nicely photographed. 7.</td>', 'A black-headed tern, I think.  Nicely photographed. 7.', '2006-08-03 18:53:26.000000', NULL, 1),
(2693163, 372486, 51538, '<td valign="top">That''s an interesting moment of stop and start, decelerate and accelerate, you caught for the viewer to analyze.  The shutter speed and exposure are very effective. 8.</td>', 'That''s an interesting moment of stop and start, decelerate and accelerate, you caught for the viewer to analyze.  The shutter speed and exposure are very effective. 8.', '2006-08-03 18:54:41.000000', NULL, 1),
(2693165, 372646, 51538, '<td valign="top">Nicely shot.  I always think the turn back into the wave surf photo lacks one thing: the wave.  It looks more like water skying than surfing.  But it is a classic surf photo format or view point. 7.</td>', 'Nicely shot.  I always think the turn back into the wave surf photo lacks one thing: the wave.  It looks more like water skying than surfing.  But it is a classic surf photo format or view point. 7.', '2006-08-03 18:55:52.000000', NULL, 1),
(2693168, 372662, 51538, '<td valign="top">That is a nice moment of drama and impending impact. The focus needs to be sharper on the main actor. 7.</td>', 'That is a nice moment of drama and impending impact. The focus needs to be sharper on the main actor. 7.', '2006-08-03 18:55:59.000000', NULL, 1),
(2693173, 372897, 51538, '<td valign="top">It''s unique in the challenge.  A hard event to photograph, what with the spectators and lighting and background distractions.  All in all, you did a pretty good job.  Now you just need to get them to come back and do it all over in a green field that looks like the Green and Pleasant Land. 6.</td>', 'It''s unique in the challenge.  A hard event to photograph, what with the spectators and lighting and background distractions.  All in all, you did a pretty good job.  Now you just need to get them to come back and do it all over in a green field that looks like the Green and Pleasant Land. 6.', '2006-08-03 18:58:31.000000', NULL, 1),
(2693177, 373240, 19064, '<td valign="top">nice composition, maybe a tad dark though? Otherwise a good shot</td>', 'nice composition, maybe a tad dark though? Otherwise a good shot', '2006-08-03 18:59:43.000000', NULL, 1),
(2693181, 373693, 31282, '<td valign="top">I''m sorry to say that but I think the photo is oversharpened.</td>', 'I''m sorry to say that but I think the photo is oversharpened.', '2006-08-03 19:01:13.000000', NULL, 1),
(2693186, 373420, 19064, '<td valign="top">excellent! 9</td>', 'excellent! 9', '2006-08-03 19:02:41.000000', NULL, 1),
(2693187, 372666, 62187, '<td valign="top">Great job...I like it!</td>', 'Great job...I like it!', '2006-08-03 19:03:19.000000', NULL, 1),
(2693190, 371300, 62187, '<td valign="top">Very crisp photo...turn it all around to catch some better lighting?</td>', 'Very crisp photo...turn it all around to catch some better lighting?', '2006-08-03 19:04:08.000000', NULL, 1),
(2693195, 372535, 62187, '<td valign="top">A little bit dark and the sky looks funny but the photo certainly shows action.</td>', 'A little bit dark and the sky looks funny but the photo certainly shows action.', '2006-08-03 19:06:03.000000', NULL, 1),
(2693200, 373527, 62187, '<td valign="top">Well done...nice photo.</td>', 'Well done...nice photo.', '2006-08-03 19:06:47.000000', NULL, 1),
(2693201, 373710, 19064, '<td valign="top">I really like this, bright and colourful, lots ging on, something different than the usual bird/sport shot. Hope you do well. 8</td>', 'I really like this, bright and colourful, lots ging on, something different than the usual bird/sport shot. Hope you do well. 8', '2006-08-03 19:07:24.000000', NULL, 1),
(2693202, 370417, 62187, '<td valign="top">Could be an advertisement for Anbesol...</td>', 'Could be an advertisement for Anbesol...', '2006-08-03 19:08:25.000000', NULL, 1),
(2693206, 373664, 70, '<td valign="top">I think this is a good idea but the action is such a small part of the shot and there''s so few people that it doesn''t really give the sense of bustle.</td>', 'I think this is a good idea but the action is such a small part of the shot and there''s so few people that it doesn''t really give the sense of bustle.', '2006-08-03 19:09:27.000000', NULL, 1),
(2693207, 372686, 19064, '<td valign="top">Excellent, this wouldn''t look out of place in the sports pages. This has to do well 9</td>', 'Excellent, this wouldn''t look out of place in the sports pages. This has to do well 9', '2006-08-03 19:10:18.000000', NULL, 1),
(2693208, 372988, 70, '<td valign="top">Good capture of the jump. Something seems a bit off in the post-processing...I''m guessing maybe you used Shadow/Highlight a bit too much? Doesn''t quite look natural.</td>', 'Good capture of the jump. Something seems a bit off in the post-processing...I''m guessing maybe you used Shadow/Highlight a bit too much? Doesn''t quite look natural.', '2006-08-03 19:10:24.000000', NULL, 1),
(2693209, 373742, 62187, '<td valign="top">It seems just a little bit to closely cropped...but then again, all these type of shots I''ve looked at are the same way. Maybe it''s the new thing?</td>', 'It seems just a little bit to closely cropped...but then again, all these type of shots I''ve looked at are the same way. Maybe it''s the new thing?', '2006-08-03 19:10:24.000000', NULL, 1),
(2693212, 372654, 70, '<td valign="top">Good action with the girls. A shallower DOF would have been nice to make the background less of a distraction. The overall photo quality unfortunately is very noisy and poor.</td>', 'Good action with the girls. A shallower DOF would have been nice to make the background less of a distraction. The overall photo quality unfortunately is very noisy and poor.', '2006-08-03 19:11:13.000000', NULL, 1),
(2693216, 373003, 70, '<td valign="top">Cool! Nice side lighting. It''d be great if there was a little less shadow on his face but I realize you can''t really pose him exactly. I like that this is a unique take on most waterskiing/wakeboarding type photos.</td>', 'Cool! Nice side lighting. It''d be great if there was a little less shadow on his face but I realize you can''t really pose him exactly. I like that this is a unique take on most waterskiing/wakeboarding type photos.', '2006-08-03 19:12:35.000000', NULL, 1),
(2693220, 373730, 54283, '<td valign="top">I love the moment, the way the knife seemes to be heading for his face, and the way he seems to look at it.<br/>good color, good angle.</td>', 'I love the moment, the way the knife seemes to be heading for his face, and the way he seems to look at it.good color, good angle.', '2006-08-03 19:13:11.000000', NULL, 1),
(2693221, 373688, 62187, '<td valign="top">Normally I would say the horizon is unlevel but in this case it''s so grossly exagerated it works.</td>', 'Normally I would say the horizon is unlevel but in this case it''s so grossly exagerated it works.', '2006-08-03 19:13:11.000000', NULL, 1),
(2693223, 373604, 70, '<td valign="top">Interesting shot and good colors but not necessarily what I''d call action.</td>', 'Interesting shot and good colors but not necessarily what I''d call action.', '2006-08-03 19:13:15.000000', NULL, 1),
(2693226, 373531, 19064, '<td valign="top">Great capture, one little bugbear is maybe the tones are a bit muted? Still, a 9</td>', 'Great capture, one little bugbear is maybe the tones are a bit muted? Still, a 9', '2006-08-03 19:13:37.000000', NULL, 1),
(2693227, 371627, 62187, '<td valign="top">I have a feeling this one will be in the top 5 if not the top 3.</td>', 'I have a feeling this one will be in the top 5 if not the top 3.', '2006-08-03 19:13:46.000000', NULL, 1),
(2693230, 370413, 70, '<td valign="top">Cute idea. I think less floor and not cutting off the top of the sign would have improved the composition a bit here.</td>', 'Cute idea. I think less floor and not cutting off the top of the sign would have improved the composition a bit here.', '2006-08-03 19:14:18.000000', NULL, 1),
(2693232, 373504, 19064, '<td valign="top">cool 9</td>', 'cool 9', '2006-08-03 19:14:43.000000', NULL, 1),
(2693237, 373735, 70, '<td valign="top">I like this photo a lot. I don''t even know why because I don''t really understand what I''m looking at, I have no idea what the title means and I really don''t see how this relates to action. But I still really like it.</td>', 'I like this photo a lot. I don''t even know why because I don''t really understand what I''m looking at, I have no idea what the title means and I really don''t see how this relates to action. But I still really like it.', '2006-08-03 19:16:12.000000', NULL, 1),
(2693246, 373185, 70, '<td valign="top">Good action but awfully distracting background - especially the trash can.</td>', 'Good action but awfully distracting background - especially the trash can.', '2006-08-03 19:18:20.000000', NULL, 1),
(2693249, 373431, 70, '<td valign="top">Cool perspective. Seems a bit underexposed.</td>', 'Cool perspective. Seems a bit underexposed.', '2006-08-03 19:19:18.000000', NULL, 1),
(2693250, 371433, 62187, '<td valign="top">Nice...I think it has potential for top 3 and I give it a 10.</td>', 'Nice...I think it has potential for top 3 and I give it a 10.', '2006-08-03 19:19:31.000000', NULL, 1),
(2693255, 372901, 70, '<td valign="top">Oh...the many ways in which that could possibly hurt! Super capture.</td>', 'Oh...the many ways in which that could possibly hurt! Super capture.', '2006-08-03 19:20:32.000000', NULL, 1),
(2693259, 370044, 62187, '<td valign="top">Could have been tilted a bit to the right.</td>', 'Could have been tilted a bit to the right.', '2006-08-03 19:22:17.000000', NULL, 1),
(2693266, 370820, 62187, '<td valign="top">Got me...nice capture...!</td>', 'Got me...nice capture...!', '2006-08-03 19:23:09.000000', NULL, 1),
(2693268, 373014, 70, '<td valign="top">Please read this tutorial on properly sizing your images for challenges. //dpchallenge.com/tutorial.php?TUTORIAL_ID=26<br/> <br/>This looks like good action but the subject is very dark and difficult to discern from the background.</td>', 'Please read this tutorial on properly sizing your images for challenges. //dpchallenge.com/tutorial.php?TUTORIAL_ID=26 This looks like good action but the subject is very dark and difficult to discern from the background.', '2006-08-03 19:23:52.000000', NULL, 1),
(2693269, 373289, 70, '<td valign="top">Please read this tutorial on properly sizing your images for challenge. It''s difficult to judge such a small image. //dpchallenge.com/tutorial.php?TUTORIAL_ID=26<br/> <br/>This one looks quite busy and yet, I''m not sure I see much depiction of action.</td>', 'Please read this tutorial on properly sizing your images for challenge. It''s difficult to judge such a small image. //dpchallenge.com/tutorial.php?TUTORIAL_ID=26 This one looks quite busy and yet, I''m not sure I see much depiction of action.', '2006-08-03 19:23:54.000000', NULL, 1),
(2693273, 371104, 70, '<td valign="top">Cute scene. I''m not especially fond of the post-processing...it seems a little pinky.</td>', 'Cute scene. I''m not especially fond of the post-processing...it seems a little pinky.', '2006-08-03 19:24:37.000000', NULL, 1),
(2693279, 373659, 70, '<td valign="top">Wow, looks like he''s really haulin'' there.</td>', 'Wow, looks like he''s really haulin'' there.', '2006-08-03 19:25:44.000000', NULL, 1),
(2693281, 372719, 62187, '<td valign="top">I wondered if somebody would go with this form of ''action''. I actually thought about it...so...nice move and nice photo!</td>', 'I wondered if somebody would go with this form of ''action''. I actually thought about it...so...nice move and nice photo!', '2006-08-03 19:26:04.000000', NULL, 1),
(2693286, 373150, 62187, '<td valign="top">The colors look funny to me...almost like it''s been overexposed?</td>', 'The colors look funny to me...almost like it''s been overexposed?', '2006-08-03 19:27:46.000000', NULL, 1),
(2693287, 371585, 62187, '<td valign="top">A little too much grain in the sky perhaps but nice idea and I love the colors!</td>', 'A little too much grain in the sky perhaps but nice idea and I love the colors!', '2006-08-03 19:28:27.000000', NULL, 1),
(2693297, 373604, 62187, '<td valign="top">For right now it''s technically just ''ideation'' - if he jumped then it would be an ''attempt''. Just kidding...the title shows humor and I like it!</td>', 'For right now it''s technically just ''ideation'' - if he jumped then it would be an ''attempt''. Just kidding...the title shows humor and I like it!', '2006-08-03 19:30:45.000000', NULL, 1),
(2693300, 371528, 62187, '<td valign="top">I want to go there! Thanks for sharing a cool moment.</td>', 'I want to go there! Thanks for sharing a cool moment.', '2006-08-03 19:31:38.000000', NULL, 1),
(2693305, 372921, 62187, '<td valign="top">Dog, water, good crop, nice stop action...nicely done!</td>', 'Dog, water, good crop, nice stop action...nicely done!', '2006-08-03 19:32:30.000000', NULL, 1),
(2693310, 372104, 62187, '<td valign="top">That''s hot!</td>', 'That''s hot!', '2006-08-03 19:33:20.000000', NULL, 1),
(2693317, 372820, 62187, '<td valign="top">It''s so abstract I kinda like it.</td>', 'It''s so abstract I kinda like it.', '2006-08-03 19:34:31.000000', NULL, 1),
(2693323, 371900, 62187, '<td valign="top">Approved for RWY9R. Have a good flight.</td>', 'Approved for RWY9R. Have a good flight.', '2006-08-03 19:36:19.000000', NULL, 1),
