(2694233, 372739, 50289, '<td valign="top">Good job catching the ball and this guys eyes.  The shadow from the flash is distracting though.</td>', 'Good job catching the ball and this guys eyes.  The shadow from the flash is distracting though.', '2006-08-04 02:29:04.000000', NULL, 1),
(2694240, 373549, 50289, '<td valign="top">What the hell!!!  Where did this guy come from?  You get points for the WOW factor.  The sky is too dark at the top and the ground at the bottom is out of focus.  And what are all the white spots?</td>', 'What the hell!!!  Where did this guy come from?  You get points for the WOW factor.  The sky is too dark at the top and the ground at the bottom is out of focus.  And what are all the white spots?', '2006-08-04 02:33:16.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2694242, 373693, 50289, '<td valign="top">Looks a little too sharpened.  Also, the water is going to drain all over my desk because the picture is tilted.</td>', 'Looks a little too sharpened.  Also, the water is going to drain all over my desk because the picture is tilted.', '2006-08-04 02:35:38.000000', NULL, 1),
(2694244, 372060, 50289, '<td valign="top">This would have been a great shot if the woman was in focus.</td>', 'This would have been a great shot if the woman was in focus.', '2006-08-04 02:36:37.000000', NULL, 1),
(2694252, 372700, 50289, '<td valign="top">IMO, a larger crop to put the runner at the left of the frame and more of the track to the right.  Then his right arm would have been in the shot.  Also, the loss of his left elbow takes away from the action.</td>', 'IMO, a larger crop to put the runner at the left of the frame and more of the track to the right.  Then his right arm would have been in the shot.  Also, the loss of his left elbow takes away from the action.', '2006-08-04 02:41:17.000000', NULL, 1),
(2694259, 372686, 50289, '<td valign="top">What a great shot! At first I didn''t like the two dogs in the back not being in focus.  But as I looked at the picture longer I realized it brought my attention to the three dogs in the front.  I love the looks on their faces, the muscles in the legs and the mud flying. (8)</td>', 'What a great shot! At first I didn''t like the two dogs in the back not being in focus.  But as I looked at the picture longer I realized it brought my attention to the three dogs in the front.  I love the looks on their faces, the muscles in the legs and the mud flying. (8)', '2006-08-04 02:46:38.000000', NULL, 1),
(2694260, 372654, 50289, '<td valign="top">Very grainy.  Too high an ISO perhaps?</td>', 'Very grainy.  Too high an ISO perhaps?', '2006-08-04 02:47:34.000000', NULL, 1),
(2694263, 373531, 50289, '<td valign="top">Another picture where I have to say "What the hell?"  Where is this poor guy going to land?  Fantastic shot!</td>', 'Another picture where I have to say "What the hell?"  Where is this poor guy going to land?  Fantastic shot!', '2006-08-04 02:49:14.000000', NULL, 1),
(2694270, 370705, 50289, '<td valign="top">A little too over saturated for my taste.  The sky looks like a fake background and the grass looks like astroturf.  Nice stop action on the girl.</td>', 'A little too over saturated for my taste.  The sky looks like a fake background and the grass looks like astroturf.  Nice stop action on the girl.', '2006-08-04 02:53:04.000000', NULL, 1),
(2694274, 373420, 30129, '<td valign="top">Good capture but I''d like to see a little bit more of what''s going on, post it without the crop!</td>', 'Good capture but I''d like to see a little bit more of what''s going on, post it without the crop!', '2006-08-04 02:55:06.000000', NULL, 1),
(2694280, 373710, 19952, '<td valign="top">Well, I know this wasn''t Joe''s -- I can see him back there! ;-) Very nice composition and lots of great colors and action.</td>', 'Well, I know this wasn''t Joe''s -- I can see him back there! ;-) Very nice composition and lots of great colors and action.', '2006-08-04 03:00:34.000000', NULL, 1),
(2694291, 372405, 49916, '<td valign="top">Great colo(u)rs.Good action shot.Imperfect cropping :(<br/> <br/><b>Shifting of pipe from the view and the door on upper right could improve it much.You should have used shallow depth of focus to make the floor out of focus.Spot focus on the water jet near the mouth is most important in this picture.It should have been spot focused.</b></td>', 'Great colo(u)rs.Good action shot.Imperfect cropping :( Shifting of pipe from the view and the door on upper right could improve it much.You should have used shallow depth of focus to make the floor out of focus.Spot focus on the water jet near the mouth is most important in this picture.It should have been spot focused.', '2006-08-04 03:13:38.000000', NULL, 1),
(2694303, 372688, 28882, '<td valign="top">really cool</td>', 'really cool', '2006-08-04 03:24:48.000000', NULL, 1),
