INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2698856, 372220, 37858, '<td valign="top">These guys are really cute.  Great colors. 8</td>', 'These guys are really cute.  Great colors. 8', '2006-08-06 06:41:05.000000', NULL, 1),
(2698857, 370162, 37858, '<td valign="top">I don''t know whether to give you the credit for this shot or to give the credit to the surfers.  I guess you get the credit for the capture, color and PP.  They get the credit for style. 9</td>', 'I don''t know whether to give you the credit for this shot or to give the credit to the surfers.  I guess you get the credit for the capture, color and PP.  They get the credit for style. 9', '2006-08-06 06:42:55.000000', NULL, 1),
(2698859, 370889, 37858, '<td valign="top">Lots of action here.  Good colors and well framed.  A bit more noise in the crowd (no pun intended) than I prefer.  Still, a solid shot. 8</td>', 'Lots of action here.  Good colors and well framed.  A bit more noise in the crowd (no pun intended) than I prefer.  Still, a solid shot. 8', '2006-08-06 06:44:42.000000', NULL, 1),
(2698862, 373253, 48479, '<td valign="top">clever capture. i would like to have seen it taken on a cleaner (greener) table ... so it has less distracting elements.</td>', 'clever capture. i would like to have seen it taken on a cleaner (greener) table ... so it has less distracting elements.', '2006-08-06 06:45:55.000000', NULL, 1),
(2698863, 372582, 37858, '<td valign="top">Ha. That''s how to beat the heat.  Great capture.</td>', 'Ha. That''s how to beat the heat.  Great capture.', '2006-08-06 06:45:58.000000', NULL, 1),
(2698864, 370563, 37858, '<td valign="top">Nice clear focus...down to the veins in his tongue.  Wouldn''t want to get too close to this one.  Good capture.</td>', 'Nice clear focus...down to the veins in his tongue.  Wouldn''t want to get too close to this one.  Good capture.', '2006-08-06 06:46:56.000000', NULL, 1),
(2698865, 370249, 37858, '<td valign="top">That''s gotta hurt.  Nice capture.</td>', 'That''s gotta hurt.  Nice capture.', '2006-08-06 06:47:35.000000', NULL, 1),
(2698867, 372120, 37858, '<td valign="top">Nice clear image with excellent timing. 8</td>', 'Nice clear image with excellent timing. 8', '2006-08-06 06:49:35.000000', NULL, 1),
(2698869, 373014, 37858, '<td valign="top">This is a bit small to see the details.  Looks like you have some good action here, though.</td>', 'This is a bit small to see the details.  Looks like you have some good action here, though.', '2006-08-06 06:51:35.000000', NULL, 1),
(2698870, 370135, 37858, '<td valign="top">Good capture.  I like the DoF all green to set him off. 8</td>', 'Good capture.  I like the DoF all green to set him off. 8', '2006-08-06 06:52:36.000000', NULL, 1),
(2698872, 372790, 37858, '<td valign="top">This is a stunningly beautiful photo...I just wish you had made it a bit larger so I could see the detail better.  I''m scoring it an 8...if it was larger so I could see more I probably would have gone higher.  Excellent composition and colors.</td>', 'This is a stunningly beautiful photo...I just wish you had made it a bit larger so I could see the detail better.  I''m scoring it an 8...if it was larger so I could see more I probably would have gone higher.  Excellent composition and colors.', '2006-08-06 06:54:26.000000', NULL, 1),
(2698874, 373654, 37858, '<td valign="top">Interesting angle...did you rotate this or is he just hanging out.<br/> <br/>Nice colors and DoF too. 8</td>', 'Interesting angle...did you rotate this or is he just hanging out. Nice colors and DoF too. 8', '2006-08-06 06:55:46.000000', NULL, 1),
(2698876, 373097, 37858, '<td valign="top">Nice telephoto shot...looks like you were in the next lane it''s so clear.  I love the look of the water around her head and arm.  9</td>', 'Nice telephoto shot...looks like you were in the next lane it''s so clear.  I love the look of the water around her head and arm.  9', '2006-08-06 06:57:21.000000', NULL, 1),
