(2708032, 372946, 12733, '<td valign="top">Nice shot of the main subject, but the busy background spoils the overall effect.</td>', 'Nice shot of the main subject, but the busy background spoils the overall effect.', '2006-08-08 23:32:10.000000', NULL, 1),
(2708036, 373717, 12733, '<td valign="top">Great action, but the background takes a lot away from it.</td>', 'Great action, but the background takes a lot away from it.', '2006-08-08 23:33:27.000000', NULL, 1),
(2708039, 373590, 12733, '<td valign="top">Interesting idea, nicely shot. I like the reflections. Did someone toss those pins? They sure don''t look like theyh were hit by a ball.</td>', 'Interesting idea, nicely shot. I like the reflections. Did someone toss those pins? They sure don''t look like theyh were hit by a ball.', '2006-08-08 23:35:13.000000', NULL, 1),
(2708043, 372988, 15511, '<td valign="top">Good catch. The dark shades should be darker</td>', 'Good catch. The dark shades should be darker', '2006-08-08 23:35:30.000000', NULL, 1),
(2708047, 373675, 61424, '<td valign="top">Nice composition .. well done!</td>', 'Nice composition .. well done!', '2006-08-08 23:36:14.000000', NULL, 1),
(2708051, 373346, 12733, '<td valign="top">The flying dirt makes the shot!</td>', 'The flying dirt makes the shot!', '2006-08-08 23:37:14.000000', NULL, 1),
(2708054, 372060, 12733, '<td valign="top">Blur implies motion - that''s good. But too much blur over too much of the picture gets confusing and loses its effect.</td>', 'Blur implies motion - that''s good. But too much blur over too much of the picture gets confusing and loses its effect.', '2006-08-08 23:38:36.000000', NULL, 1),
(2708055, 372486, 15511, '<td valign="top">This is great. The expressions, frozen in time...</td>', 'This is great. The expressions, frozen in time...', '2006-08-08 23:38:44.000000', NULL, 1),
(2708061, 373307, 12733, '<td valign="top">Too bad it''s basic editing. Otherwise you could have cloned your arm out, and the effect would have been perfect. Nice shot, well trained dog.</td>', 'Too bad it''s basic editing. Otherwise you could have cloned your arm out, and the effect would have been perfect. Nice shot, well trained dog.', '2006-08-08 23:40:43.000000', NULL, 1),
(2708063, 370075, 12733, '<td valign="top">Great idea, but poor exposure and focus.</td>', 'Great idea, but poor exposure and focus.', '2006-08-08 23:41:31.000000', NULL, 1),
(2708069, 373014, 12733, '<td valign="top">Too small, too dark - I can hardly see what the subject of this picture is.</td>', 'Too small, too dark - I can hardly see what the subject of this picture is.', '2006-08-08 23:42:25.000000', NULL, 1),
(2708072, 372967, 61424, '<td valign="top">Would have been nice in colour!</td>', 'Would have been nice in colour!', '2006-08-08 23:42:50.000000', NULL, 1),
