(2708094, 370179, 61424, '<td valign="top">Awesome capture!</td>', 'Awesome capture!', '2006-08-08 23:46:14.000000', NULL, 1),
(2708100, 373017, 61424, '<td valign="top">Perfect! Very clear .. well done.</td>', 'Perfect! Very clear .. well done.', '2006-08-08 23:46:42.000000', NULL, 1),
